CREATE TABLE ad.competencies (id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY, code text NOT NULL UNIQUE, active boolean NOT NULL DEFAULT true);
CREATE TABLE ad.competency_versions (id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY, competency_id integer NOT NULL REFERENCES ad.competencies(id), version integer NOT NULL, name text NOT NULL, description text NOT NULL, category text NOT NULL, weight numeric NOT NULL CHECK(weight>0), position_id integer REFERENCES ad.positions(id), created_by integer NOT NULL REFERENCES ad.users(id), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(competency_id,version));
CREATE TABLE ad.questions (id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY, competency_id integer NOT NULL REFERENCES ad.competencies(id), active boolean NOT NULL DEFAULT true);
CREATE TABLE ad.question_versions (id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY, question_id integer NOT NULL REFERENCES ad.questions(id), version integer NOT NULL, prompt text NOT NULL, scale jsonb NOT NULL CHECK(jsonb_array_length(scale)=5), created_by integer NOT NULL REFERENCES ad.users(id), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(question_id,version));
CREATE TABLE ad.questionnaires (id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY, name text NOT NULL, position_id integer NOT NULL REFERENCES ad.positions(id), active boolean NOT NULL DEFAULT true);
CREATE TABLE ad.questionnaire_versions (id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY, questionnaire_id integer NOT NULL REFERENCES ad.questionnaires(id), version integer NOT NULL, snapshot jsonb NOT NULL, created_by integer NOT NULL REFERENCES ad.users(id), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(questionnaire_id,version));
CREATE TABLE ad.evaluation_cycles (id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY, name text NOT NULL, reference_start date NOT NULL, reference_end date NOT NULL CHECK(reference_end>=reference_start), opens_on date NOT NULL, deadline date NOT NULL CHECK(deadline>=opens_on), periodicity_months integer NOT NULL CHECK(periodicity_months>0), status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','open','closed')), role_weights jsonb NOT NULL, divergence_limit numeric NOT NULL CHECK(divergence_limit BETWEEN 0 AND 4), created_by integer NOT NULL REFERENCES ad.users(id), created_at timestamptz NOT NULL DEFAULT now(), closed_at timestamptz);
CREATE TABLE ad.cycle_participants (id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY, cycle_id integer NOT NULL REFERENCES ad.evaluation_cycles(id), employee_id integer NOT NULL REFERENCES ad.employees(id), questionnaire_version_id integer NOT NULL REFERENCES ad.questionnaire_versions(id), responsible_id integer REFERENCES ad.users(id), released boolean NOT NULL DEFAULT false, released_at timestamptz, UNIQUE(cycle_id,employee_id));
CREATE TABLE ad.evaluation_assignments (id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY, participant_id integer NOT NULL REFERENCES ad.cycle_participants(id), evaluator_id integer NOT NULL REFERENCES ad.users(id), profile text NOT NULL, kind text NOT NULL CHECK(kind IN ('self','manager')), weight numeric NOT NULL CHECK(weight>0), status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','submitted','superseded')), predecessor_id integer REFERENCES ad.evaluation_assignments(id), review_needed boolean NOT NULL DEFAULT false, version integer NOT NULL DEFAULT 0, submitted_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX evaluation_unique_active ON ad.evaluation_assignments(participant_id,evaluator_id,kind) WHERE status<>'superseded';
CREATE INDEX evaluation_assignee ON ad.evaluation_assignments(evaluator_id,status);
CREATE TABLE ad.evaluation_responses (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, assignment_id integer NOT NULL REFERENCES ad.evaluation_assignments(id), revision integer NOT NULL, answers jsonb NOT NULL, submitted boolean NOT NULL DEFAULT false, author_id integer NOT NULL REFERENCES ad.users(id), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(assignment_id,revision));
CREATE TABLE ad.evaluation_transfers (id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY, participant_id integer NOT NULL REFERENCES ad.cycle_participants(id), assignment_id integer REFERENCES ad.evaluation_assignments(id), previous_evaluator_id integer REFERENCES ad.users(id), next_evaluator_id integer REFERENCES ad.users(id), reason text NOT NULL, decision text CHECK(decision IN ('accept','discard')), decision_reason text, decided_by integer REFERENCES ad.users(id), created_by integer NOT NULL REFERENCES ad.users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE ad.evaluation_result_releases (id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY, participant_id integer NOT NULL REFERENCES ad.cycle_participants(id), released boolean NOT NULL, snapshot jsonb, reason text NOT NULL, user_id integer NOT NULL REFERENCES ad.users(id), created_at timestamptz NOT NULL DEFAULT now());
